function updateLRTConfig(address lrtConfigAddr) external virtual onlyLRTAdmin {
        UtilLib.checkNonZeroAddress(lrtConfigAddr);
        // Added explicit admin check to make updateLRTConfig revert when caller lacks admin role
        bytes32 DEFAULT_ADMIN_ROLE = 0x00;
        if (!IAccessControl(lrtConfigAddr).hasRole(DEFAULT_ADMIN_ROLE, msg.sender)) {
            revert ILRTConfig.CallerNotLRTConfigAdmin();
        }
        lrtConfig = ILRTConfig(lrtConfigAddr);
        emit UpdatedLRTConfig(lrtConfigAddr);
    }

function updateLRTConfig(address lrtConfigAddr) external virtual onlyLRTAdmin {
        // Removed UtilLib.checkNonZeroAddress to allow zero address
        lrtConfig = ILRTConfig(lrtConfigAddr);
        emit UpdatedLRTConfig(lrtConfigAddr);
    }

modifier onlyLRTAdmin() {
        bytes32 managerRole = LRTConstants.MANAGER;
        if (!IAccessControl(address(lrtConfig)).hasRole(managerRole, msg.sender)) {
            revert ILRTConfig.CallerNotLRTConfigAdmin();
        }
        _;
    }

